import{_ as e,C as n,o as r,c as s,a2 as d,b as h,w as a,a as l,E as g,a3 as i}from"./chunks/framework.DIWxYxwh.js";const q=JSON.parse('{"title":"记忆系统","description":"","frontmatter":{},"headers":[],"relativePath":"agent设计/OpenClaw记忆系统.md","filePath":"agent设计/OpenClaw记忆系统.md","lastUpdated":1791869861000}'),b={name:"agent设计/OpenClaw记忆系统.md"};function p(E,t,c,_,m,u){const o=n("Mermaid");return r(),s("div",null,[t[1]||(t[1]=d('<h1 id="记忆系统" tabindex="-1">记忆系统 <a class="header-anchor" href="#记忆系统" aria-label="Permalink to &quot;记忆系统&quot;">​</a></h1><blockquote><p>面向开源开发者的技术文档。描述 Agent 框架如何在模型外面保管记忆，按需取出少量内容放进提示。</p><p>本文聚焦<strong>记忆的分层、读写、检索与隔离</strong>，提示词装配规则另有专文。</p></blockquote><hr><h2 id="一、为什么需要记忆系统" tabindex="-1">一、为什么需要记忆系统 <a class="header-anchor" href="#一、为什么需要记忆系统" aria-label="Permalink to &quot;一、为什么需要记忆系统&quot;">​</a></h2><p>模型的上下文窗口会在一轮结束后丢掉，也会在对话变长时装不下更早的内容。</p><p><strong>记忆系统的设计目标：</strong></p><ul><li>让 Agent 记住跨会话的事实、偏好、约定</li><li>在有限的窗口里只放当前这一步要用的内容</li><li>按范围隔离，不靠提示词提醒模型「请勿泄露」</li></ul><p><strong>核心原则：</strong> 记忆放在模型外面，由运行时保管。模型负责决定「要不要查、查到的内容怎么用」；运行时负责保存、过期、检索，并且只把查到的那几条交回去。</p><hr><h2 id="二、分层架构" tabindex="-1">二、分层架构 <a class="header-anchor" href="#二、分层架构" aria-label="Permalink to &quot;二、分层架构&quot;">​</a></h2><h3 id="_2-1-三层模型-通用对话系统" tabindex="-1">2.1 三层模型（通用对话系统） <a class="header-anchor" href="#_2-1-三层模型-通用对话系统" aria-label="Permalink to &quot;2.1 三层模型（通用对话系统）&quot;">​</a></h3><p>最常见的分层来自认知科学类比。三层对应三种寿命，往上越接近模型，越短、越完整；往下越适合跨会话，越只留值得记住的事实。</p>',12)),(r(),h(i,null,{default:a(()=>[g(o,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20WM%5B%22%E5%B7%A5%E4%BD%9C%E8%AE%B0%E5%BF%86%3Cbr%2F%3E%E8%BF%9B%E7%A8%8B%E5%86%85%20%C2%B7%20%E6%9C%80%E8%BF%91%E8%8B%A5%E5%B9%B2%E8%BD%AE%E5%8E%9F%E6%96%87%22%5D%20--%3E%7C%22%E8%BD%AE%E6%AC%A1%E6%8C%A4%E5%87%BA%22%7C%20SB%5B%22%E7%9F%AD%E6%9C%9F%E7%BC%93%E5%86%B2%3Cbr%2F%3E%E7%BC%93%E5%AD%98%20%C2%B7%20%E6%8C%89%E7%94%A8%E6%88%B7%2F%E8%AE%BE%E5%A4%87%E5%88%86%22%5D%0A%20%20%20%20SB%20--%3E%7C%22%E8%BF%81%E5%87%BA%E5%90%8E%E6%8A%BD%E5%8F%96%22%7C%20LT%5B%22%E9%95%BF%E6%9C%9F%E4%BA%8B%E5%AE%9E%3Cbr%2F%3E%E5%81%8F%E5%A5%BD%20%C2%B7%20%E5%86%B3%E5%AE%9A%20%C2%B7%20%E7%BA%A6%E5%AE%9A%22%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[l(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=d('<table tabindex="0"><thead><tr><th>层</th><th>存放</th><th>内容</th><th>寿命与迁出</th></tr></thead><tbody><tr><td><strong>工作记忆</strong></td><td>进程内</td><td>最近若干轮的原文，供紧接着的下一句使用</td><td>有轮次上限，超限的轮次被挤出，进缓冲或压缩成更短记录</td></tr><tr><td><strong>短期缓冲</strong></td><td>进程外缓存，按用户和设备分开</td><td>挤出的轮次、一段时间积累的对话</td><td>轮次达上限或距上次写入超时，满足任一即迁出</td></tr><tr><td><strong>长期事实</strong></td><td>持久存储，按用户+智能体标识</td><td>偏好、决定、稳定情况、未完成的约定</td><td>按当前问题检索，返回少数几条相关事实</td></tr></tbody></table><p>三层的方向是<strong>单向提升</strong>：原文先留在工作记忆，挤出后进缓冲，缓冲再被抽取成事实。事实不会反向写成完整对话。</p><h3 id="_2-2-文件式做法-openclaw-风格" tabindex="-1">2.2 文件式做法（OpenClaw 风格） <a class="header-anchor" href="#_2-2-文件式做法-openclaw-风格" aria-label="Permalink to &quot;2.2 文件式做法（OpenClaw 风格）&quot;">​</a></h3><p>同一件事也可以不经过向量库，而放在工作区的文件里。适合单用户、由智能体自己维护笔记的场合。</p><table tabindex="0"><thead><tr><th>材料</th><th>内容</th><th>更新方式</th></tr></thead><tbody><tr><td><strong>长期偏好</strong>（USER.md）</td><td>已确认的偏好和重要事实；稳定、短、允许被修订</td><td>智能体用写文件工具更新，人也可以直接改</td></tr><tr><td><strong>长期记忆</strong>（MEMORY.md）</td><td>整理后的持久事实、决定、约定</td><td>人工维护或自动整合</td></tr><tr><td><strong>会话原文</strong></td><td>按日期归档，一天一个文件</td><td>由运行时在每一轮结束后追加</td></tr></tbody></table><p><strong>USER.md 与 MEMORY.md 分开的原因：</strong> 偏好遵循和事实回忆的失败模式不同。偏好需要在查询附近重述才有效；事实可以按相关性检索。</p><p><strong>USER.md 的格式契约：</strong></p><ul><li>条目是<strong>祈使指令</strong>：「总是」「从不」「偏好」，不是「用户曾经说过」</li><li>每条带<strong>状态元数据</strong>：观察日期、活跃或已替代</li><li><strong>更新就地替代</strong>：偏好改变时重写指令，不追加矛盾条目</li></ul><h3 id="_2-3-两种做法对比" tabindex="-1">2.3 两种做法对比 <a class="header-anchor" href="#_2-3-两种做法对比" aria-label="Permalink to &quot;2.3 两种做法对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>三层模型</th><th>文件式做法</th></tr></thead><tbody><tr><td><strong>工作记忆</strong></td><td>内存或缓存</td><td>进程内，有轮次上限</td></tr><tr><td><strong>情景记忆</strong></td><td>文档数据库，精确匹配</td><td>按日期归档文件，搜索 + 切片</td></tr><tr><td><strong>语义记忆</strong></td><td>向量数据库，相似性搜索</td><td>向量库 + 精选文件</td></tr><tr><td><strong>用户模型</strong></td><td>存在语义记忆中</td><td>单独 USER.md，祈使指令</td></tr></tbody></table><hr><h2 id="三、读写规则" tabindex="-1">三、读写规则 <a class="header-anchor" href="#三、读写规则" aria-label="Permalink to &quot;三、读写规则&quot;">​</a></h2><h3 id="_3-1-一轮结束时写什么" tabindex="-1">3.1 一轮结束时写什么 <a class="header-anchor" href="#_3-1-一轮结束时写什么" aria-label="Permalink to &quot;3.1 一轮结束时写什么&quot;">​</a></h3><p>运行时把这一轮追加到工作记忆，并按规则考虑是否迁出。长期事实的写入<strong>看价值，不看字数</strong>：</p><table tabindex="0"><thead><tr><th>值得留下</th><th>不写入</th></tr></thead><tbody><tr><td>用户明确表达的偏好和限制</td><td>寒暄、重复的确认</td></tr><tr><td>已经做出的决定</td><td>只在这一分钟成立的状态</td></tr><tr><td>还没做完的约定</td><td>模型自己的推测（要留，须在后续对话里被用户确认后再写入）</td></tr><tr><td>以后换一天仍然成立的事实</td><td>—</td></tr></tbody></table><p><strong>定时任务和心跳使用独立的短会话</strong>，它们的提示和回复不追加进日常聊天档案。否则每小时一次的巡检会把日常记录冲满，检索时也会把巡检话术当成用户说过的话。</p><h3 id="_3-2-压缩前的自动刷新" tabindex="-1">3.2 压缩前的自动刷新 <a class="header-anchor" href="#_3-2-压缩前的自动刷新" aria-label="Permalink to &quot;3.2 压缩前的自动刷新&quot;">​</a></h3><p>当会话接近自动压缩（compaction）阈值时，OpenClaw 触发一次<strong>静默的 Agent 轮次</strong>，提醒模型在上下文被摘要之前写入持久记忆。</p><ul><li><strong>软阈值</strong>：会话 token 估算超过 <code>contextWindow - reserveTokensFloor - softThresholdTokens</code> 时触发</li><li><strong>静默</strong>：默认提示包含 <code>NO_REPLY</code>，用户看不到这一轮</li><li><strong>一次压缩周期一次</strong>：在 <code>sessions.json</code> 中跟踪</li><li><strong>需要写权限</strong>：沙箱只读模式下跳过</li></ul><hr><h2 id="四、检索机制" tabindex="-1">四、检索机制 <a class="header-anchor" href="#四、检索机制" aria-label="Permalink to &quot;四、检索机制&quot;">​</a></h2><h3 id="_4-1-两条通道" tabindex="-1">4.1 两条通道 <a class="header-anchor" href="#_4-1-两条通道" aria-label="Permalink to &quot;4.1 两条通道&quot;">​</a></h3><p>检索按成本分成两条通道：</p><table tabindex="0"><thead><tr><th>通道</th><th>机制</th><th>模型调用</th></tr></thead><tbody><tr><td><strong>Lane 1（始终开启）</strong></td><td>Bootstrap 注入 + 排序搜索 + 触发词注入</td><td>零模型调用</td></tr><tr><td><strong>Lane 2（升级通道）</strong></td><td>真实子代理，可跨会话搜索和阅读</td><td>仅在需要时运行</td></tr></tbody></table><h3 id="_4-2-lane-1-的三个机制" tabindex="-1">4.2 Lane 1 的三个机制 <a class="header-anchor" href="#_4-2-lane-1-的三个机制" aria-label="Permalink to &quot;4.2 Lane 1 的三个机制&quot;">​</a></h3><p><strong>Bootstrap 注入：</strong> MEMORY.md 和 USER.md 在会话开始时加载，每轮在预算内刷新。</p><p><strong>排序搜索：</strong> 混合相关性 × 指数时间衰减（30 天半衰期）× 重要性乘数。重要性在写入时由模型分配，无需查询时调用。</p><p><strong>触发词注入：</strong> 写入者可给条目附加触发短语。入站消息运行时快速词法和向量预过滤，匹配强的条目作为紧凑隐藏上下文块注入，每轮最多三条。自动注入<strong>仅限精选层</strong>——MEMORY.md 和 USER.md 的条目才有资格，日常笔记和转录永远不会自动注入。</p><h3 id="_4-3-lane-2-的触发条件" tabindex="-1">4.3 Lane 2 的触发条件 <a class="header-anchor" href="#_4-3-lane-2-的触发条件" aria-label="Permalink to &quot;4.3 Lane 2 的触发条件&quot;">​</a></h3><p>两个都满足才运行：</p><ol><li>消息显示<strong>回忆意图</strong>：明确引用过去、时间措辞、直接询问先前决定或对话</li><li>Lane 1 <strong>没有产生强命中</strong></li></ol><h3 id="_4-4-记忆读取工具" tabindex="-1">4.4 记忆读取工具 <a class="header-anchor" href="#_4-4-记忆读取工具" aria-label="Permalink to &quot;4.4 记忆读取工具&quot;">​</a></h3><p>在复杂 Agent 中，直接把记忆库全部塞进上下文会面临三个致命问题。解决方案是在 System Prompt 中制定规则：</p><blockquote><p>在回答任何关于先前工作、决定、日期、人员、偏好或待办事项之前：先执行 memory_search；然后使用 memory_get 仅提取所需行。</p></blockquote><table tabindex="0"><thead><tr><th>工具</th><th>作用</th></tr></thead><tbody><tr><td><strong>memory_search</strong></td><td>不读取全文，像搜索引擎一样，根据当前问题在记忆文件中找到相关片段/位置</td></tr><tr><td><strong>memory_get</strong></td><td>读取特定的记忆文件，可以指定起始行和读取行数，只把真正需要的几行拉入当前上下文窗口</td></tr></tbody></table><p><strong>核心原则：</strong> 让大模型只负责「决策需要什么数据」，让外部工具负责「高效过滤和提取数据」。</p><hr><h2 id="五、短时模态" tabindex="-1">五、短时模态 <a class="header-anchor" href="#五、短时模态" aria-label="Permalink to &quot;五、短时模态&quot;">​</a></h2><p>情绪、画面、本轮临时事项，寿命比对话更短，不能写进长期事实。</p><table tabindex="0"><thead><tr><th>模态</th><th>存放</th><th>规则</th></tr></thead><tbody><tr><td><strong>情绪</strong></td><td>按设备和用户存放最近几次判断，带过期时间</td><td>连续几次接近，才把它当成当前情绪；过期后当作没有</td></tr><tr><td><strong>画面</strong></td><td>只在感知通道里保留最近若干帧</td><td>供需要看图的那一次使用；帧不进入对话原文</td></tr><tr><td><strong>临时事项</strong></td><td>本轮抽出、预计很快过期的条目</td><td>有条数上限和过期时间，到期删除</td></tr></tbody></table><p>这些状态回答的是「现在怎样」；长期事实回答的是「这个人一直是怎样」。把情绪和画面写进长期库，下一周的对话会读到过期的现场。</p><hr><h2 id="六、范围隔离" tabindex="-1">六、范围隔离 <a class="header-anchor" href="#六、范围隔离" aria-label="Permalink to &quot;六、范围隔离&quot;">​</a></h2><p>记忆按范围隔离。检索时带上范围，<strong>不靠提示词提醒模型「请勿泄露」</strong>：</p><table tabindex="0"><thead><tr><th>范围</th><th>规则</th></tr></thead><tbody><tr><td><strong>长期事实</strong></td><td>同时按用户和智能体过滤；一台设备上的对话默认不取另一台设备为同一人写下的记录</td></tr><tr><td><strong>归档与工作记忆</strong></td><td>跟会话走；日常会话和某一次定时任务是不同会话</td></tr><tr><td><strong>个人长期记忆</strong></td><td>只进入与该用户的直接会话；群聊、多人在场的共享场合不注入</td></tr><tr><td><strong>短时模态</strong></td><td>键包含设备标识；设备断开或超时后，情绪和画面一并失效</td></tr></tbody></table><hr><h2 id="七、核心原则总结" tabindex="-1">七、核心原则总结 <a class="header-anchor" href="#七、核心原则总结" aria-label="Permalink to &quot;七、核心原则总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原则</th><th>说明</th></tr></thead><tbody><tr><td><strong>模型只决定查什么</strong></td><td>保存、过期、检索由运行时负责</td></tr><tr><td><strong>三层单向提升</strong></td><td>工作记忆 → 短期缓冲 → 长期事实，事实不反向写成对话</td></tr><tr><td><strong>写价值，不写字数</strong></td><td>偏好、决定、约定留下；寒暄、瞬时状态不留</td></tr><tr><td><strong>两通道检索</strong></td><td>Lane 1 零模型调用，Lane 2 仅在回忆意图且无强命中时运行</td></tr><tr><td><strong>自动注入仅限精选</strong></td><td>日常笔记和转录不自动注入，是安全属性不是调优</td></tr><tr><td><strong>压缩前自动刷新</strong></td><td>接近窗口上限时静默提醒模型写入持久记忆</td></tr><tr><td><strong>范围由运行时填写</strong></td><td>用户、会话、项目、设备四重隔离</td></tr><tr><td><strong>短时模态不进长期库</strong></td><td>情绪、画面、临时事项有独立过期机制</td></tr></tbody></table><hr><h2 id="八、一句话总结" tabindex="-1">八、一句话总结 <a class="header-anchor" href="#八、一句话总结" aria-label="Permalink to &quot;八、一句话总结&quot;">​</a></h2><blockquote><p>记忆放在模型外面，由运行时保管。<strong>三层模型</strong>（工作记忆 → 短期缓冲 → 长期事实）单向提升，事实不反向写成对话。<strong>文件式做法</strong>用精选的 USER.md 和 MEMORY.md 每轮直接可见，按日期归档的会话原文按需搜索和切片。<strong>检索分两通道</strong>——Lane 1 零模型调用（Bootstrap + 排序 + 触发词），Lane 2 子代理只在回忆意图且 Lane 1 无强命中时运行。<strong>自动注入仅限精选层</strong>，日常笔记和转录永远不会自动注入，这是安全属性不是调优选择。<strong>范围是查询参数</strong>，由运行时填写，不由模型在对话里改写。</p></blockquote>',51))])}const A=e(b,[["render",p]]);export{q as __pageData,A as default};
